WITH max_date AS (
    SELECT MAX(order_date) AS md FROM orders
),
target_month AS (
    SELECT strftime('%Y-%m', date(md, '-1 month')) AS ym FROM max_date
)
SELECT SUM(o.total_amount) AS total_value
FROM orders o
JOIN target_month t ON strftime('%Y-%m', o.order_date) = t.ym
WHERE o.status = 'completed';

